#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;
namespace FileCompass {
 internal static class UnifiedSearchTests {
  internal static int Run(string root){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"alpha.txt"),"alpha");File.WriteAllText(Path.Combine(root,"beta.txt"),"beta");var log=new List<string>();MainWindow main=null;try{Action<bool,string> check=delegate(bool ok,string label){if(!ok)throw new Exception(label);log.Add(label);};L.ChangeLanguage("cs");main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){Width=1740,Height=900,Left=-18000,Top=-18000,ShowActivated=false};main.Show();NavigationTests.WaitPanels(main);main.Activate();main.VerifyUnifiedSearch(check,root);File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count}));main.Close();main=null;return 0;}catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(main!=null)main.Close();}}
 }
 public partial class MainWindow {
  internal void VerifyUnifiedSearch(Action<bool,string> check,string root){
   check(CommandSearchMatches("Přejmenovat","přejmenování")&&CommandSearchMatches("Hromadné přejmenování…","prejmenovani")&&!CommandSearchMatches("Kopírovat","přejmenování"),"command search finds both rename actions with or without accents");
   SetActive(left);left.List.Focus();UpdateLayout();var frame=FluentUiTests.Children<Border>(this).Single(x=>Convert.ToString(x.Tag)=="main-toolbar-frame");var buttons=AdvancedToolsTests.Visual<Button>(frame).Where(x=>Convert.ToString(x.Tag)=="toolbar-action").ToArray();Func<string,Button> button=name=>buttons.Single(x=>FluentUiTests.Children<Image>(x).Any(i=>Convert.ToString(i.Tag)==name));
   check(!buttons.Any(x=>FluentUiTests.Children<Image>(x).Any(i=>Convert.ToString(i.Tag)=="search"))&&FluentUiTests.Children<Button>(frame).Any(x=>System.Windows.Automation.AutomationProperties.GetAutomationId(x)=="AdvancedSearch"),"advanced search is in the upper search field instead of the toolbar");
   var settings=button("settings");check(settings.TranslatePoint(new Point(),frame).X>button("ftp").TranslatePoint(new Point(),frame).X&&fluentSearchInput.TranslatePoint(new Point(),frame).X>settings.TranslatePoint(new Point(),frame).X,"settings and the single search field are aligned on the right");
   var back=button("back");var sync=button("sync");check(Object.ReferenceEquals(((FrameworkElement)back.Parent).Parent,sync.Parent)&&sync.TranslatePoint(new Point(),frame).X>back.TranslatePoint(new Point(),frame).X,"synchronization is next to the two cross-panel arrows");
   check(buttons.All(x=>!Object.Equals(((SolidColorBrush)x.Background).Color,Colors.White)),"all toolbar buttons have tinted resting backgrounds");
   foreach(bool enabled in new[]{true,false}){SetToolbarState(toolbarThumbnailsButton,enabled);UpdateLayout();var mark=(Border)toolbarThumbnailsButton.Template.FindName("ActiveMark",toolbarThumbnailsButton);check(mark.IsVisible==enabled&&((bool)toolbarThumbnailsButton.GetValue(FluentToolbarUx.ActiveProperty))==enabled,"toggle state has a persistent underline: "+enabled);check(((SolidColorBrush)toolbarThumbnailsButton.Background).Color!=Colors.White,"toggle state never uses a white resting background");}UpdateViewToolbarControls();
   Action<string> type=text=>{var composition=new TextComposition(InputManager.Current,left.List,text);var args=new TextCompositionEventArgs(Keyboard.PrimaryDevice,composition){RoutedEvent=TextCompositionManager.PreviewTextInputEvent};left.List.RaiseEvent(args);check(args.Handled,"file-list typing is routed into shared search: "+text);};
   type("al");check(fluentSearchInput.Text=="al"&&left.List.Items.Cast<Entry>().Any(x=>x.FullName=="alpha.txt")&&!left.List.Items.Cast<Entry>().Any(x=>x.FullName=="beta.txt"),"typing in file list updates upper search and filters files [field="+fluentSearchInput.Text+", panel="+left.QuickFilterText+", activeLeft="+(active==left)+", rows="+String.Join(",",left.List.Items.Cast<Entry>().Select(x=>x.Name))+"]");
   check(!left.HasVisibleQuickBar&&!right.HasVisibleQuickBar,"no bottom search bar appears in either panel");
   string folder=left.CurrentPath;var erase=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(this),0,Key.Back){RoutedEvent=Keyboard.PreviewKeyDownEvent};left.List.RaiseEvent(erase);check(erase.Handled&&fluentSearchInput.Text=="a"&&left.CurrentPath==folder,"Backspace edits search without navigating to the parent folder");
   var space=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(this),0,Key.Space){RoutedEvent=Keyboard.PreviewKeyDownEvent};left.List.RaiseEvent(space);check(space.Handled&&fluentSearchInput.Text=="a ","Space extends an active search rather than marking a file");
   left.SetQuickFilter("al");SetActive(right);check(fluentSearchInput.Text=="","switching panels shows that panel's own filter");fluentSearchInput.Text="be";check(right.QuickFilterText=="be"&&left.QuickFilterText=="al","editing global field filters only the active panel");SetActive(left);check(fluentSearchInput.Text=="al","returning to panel restores its query in the shared field");left.FocusFilter();check(fluentSearchInput.IsKeyboardFocused&&!left.HasVisibleQuickBar,"focus-filter command targets the upper field");
   fluentSearchInput.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(this),0,Key.Escape){RoutedEvent=Keyboard.KeyDownEvent});check(fluentSearchInput.Text==""&&left.QuickFilterText=="","Escape clears global search and panel filter together");
   left.SetQuickFilter("alpha");fluentSearchInput.Focus();fluentSearchInput.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(this),0,Key.Enter){RoutedEvent=Keyboard.KeyDownEvent});check(left.List.IsKeyboardFocusWithin,"Enter returns from the search field to file results");NextStageTests.Draw(this,Path.Combine(root,"search.png"));left.SetQuickFilter("");right.SetQuickFilter("");
   var gallery=new StackPanel{Orientation=Orientation.Horizontal,Background=CompactTheme.PanelSurface};foreach(string mode in new[]{"SideBySide","Stacked","Single"}){var tile=new StackPanel{Margin=new Thickness(16)};tile.Children.Add(new Image{Source=PanelLayoutSymbols.Get("panels-"+mode,ToolbarTheme.Classic),Width=48,Height=48});tile.Children.Add(new TextBlock{Text=L.Text(mode=="Single"?"toolbar.panelsSingle":mode=="Stacked"?"toolbar.panelsStacked":"toolbar.panelsSideBySide"),Margin=new Thickness(0,8,0,0)});gallery.Children.Add(tile);}var preview=new Window{Width=600,Height=180,Content=gallery,Left=-18000,Top=-18000};preview.Show();NextStageTests.Draw(preview,Path.Combine(root,"panel-icons.png"));preview.Close();
   foreach(double width in new[]{1280.0,960.0}){Width=width;UpdateLayout();foreach(var b in buttons.Where(x=>x.IsVisible)){var point=b.TranslatePoint(new Point(b.ActualWidth,b.ActualHeight),frame);check(point.X<=frame.ActualWidth+1&&point.Y<=frame.ActualHeight+1,"toolbar control remains inside reflowing frame at "+width);}check(fluentSearchInput.IsVisible&&fluentSearchInput.TranslatePoint(new Point(fluentSearchInput.ActualWidth,0),this).X<=ActualWidth,"upper search remains accessible at "+width);NextStageTests.Draw(this,Path.Combine(root,"toolbar-"+width+".png"));}
  }
 }
 public partial class FilePanel {internal bool HasVisibleQuickBar{get{return quickBar.IsVisible;}}}
}
#endif
